const mongoose = require('mongoose');
const crypto = require('crypto');

const WarrantySchema = new mongoose.Schema(
  {
    type: {
      type: String,
      enum: ['No warranty', 'Manufacturer warranty', 'Extended warranty'],
    },
    period: {
      type: String,
      default: '',
      trim: true,
    },
    coverage: {
      type: [String],
      default: [],
    },
  },
  { _id: false }
);

const ReturnPolicySchema = new mongoose.Schema(
  {
    returnable: {
      type: Boolean,
      default: false,
    },
    returnPeriodDays: {
      type: Number,
      default: 0,
      min: 0,
    },
    conditions: {
      type: [String],
      default: [],
    },
  },
  { _id: false }
);

const ProductSchema = new mongoose.Schema(
  {
    name: {
      type: String,
      required: true,
      trim: true,
    },
    category: {
      type: String,
      required: true,
      trim: true,
    },
    subcategory: {
      type: String,
      default: '',
      trim: true,
    },
    model: {
      type: String,
      default: '',
      trim: true,
    },
    color: {
      type: String,
      default: '',
      trim: true,
    },
    styleTheme: {
      type: String,
      default: '',
      trim: true,
    },
    price: {
      type: Number,
      min: 0,
      default: 0,
    },
    mrp: {
      type: Number,
      min: 0,
      default: 0,
    },
    discountAmount: {
      type: Number,
      min: 0,
      default: 0,
    },
    discountPercentage: {
      type: Number,
      min: 0,
      max: 100,
      default: 0,
    },
    discountStartDate: {
      type: Date,
      default: null,
    },
    discountEndDate: {
      type: Date,
      default: null,
    },
    description: {
      type: String,
      default: '',
      trim: true,
    },
    expiryApplicable: {
      type: Boolean,
      default: false,
    },
    image: {
      type: String,
      default: '',
      trim: true,
    },
    imageVariants: {
      type: mongoose.Schema.Types.Mixed,
      default: null,
    },
    imagePublicId: {
      type: String,
      default: '',
      trim: true,
    },
    imageCdn: {
      type: String,
      default: '',
      trim: true,
    },
    stock: {
      type: Number,
      min: 0,
      default: 0,
    },
    rating: {
      type: Number,
      min: 0,
      max: 5,
      default: 0,
    },
    reviewCount: {
      type: Number,
      min: 0,
      default: 0,
    },
    views: {
      type: Number,
      min: 0,
      default: 0,
    },
    clicks: {
      type: Number,
      min: 0,
      default: 0,
    },
    unitsSold: {
      type: Number,
      min: 0,
      default: 0,
    },
    lastSoldAt: {
      type: Date,
      default: null,
    },
    manufacturingDate: {
      type: Date,
      default: null,
    },
    expiryDate: {
      type: Date,
      default: null,
    },
    inventoryBatches: [
      {
        id: {
          type: String,
          default: () => crypto.randomUUID(),
        },
        batchLabel: {
          type: String,
          default: '',
          trim: true,
        },
        stock: {
          type: Number,
          required: true,
          min: 0,
        },
        price: {
          type: Number,
          required: true,
          min: 0,
        },
        mrp: {
          type: Number,
          required: true,
          min: 0,
        },
        location: {
          type: String,
          default: '',
          trim: true,
        },
        discountAmount: {
          type: Number,
          min: 0,
          default: 0,
        },
        discountPercentage: {
          type: Number,
          min: 0,
          max: 100,
          default: 0,
        },
        discountStartDate: {
          type: Date,
          default: null,
        },
        discountEndDate: {
          type: Date,
          default: null,
        },
        manufacturingDate: {
          type: Date,
          default: null,
        },
        expiryDate: {
          type: Date,
          default: null,
        },
        returnAllowed: {
          type: Boolean,
          default: false,
        },
        returnWindowDays: {
          type: Number,
          min: 0,
          default: 0,
        },
        createdAt: {
          type: Date,
          default: Date.now,
        },
        isActive: {
          type: Boolean,
          default: true,
        },
      },
    ],
    sellerName: {
      type: String,
      required: true,
      trim: true,
    },
    businessName: {
      type: String,
      required: true,
      trim: true,
    },
    sellerEmail: {
      type: String,
      required: true,
      lowercase: true,
      trim: true,
      index: true,
    },
    isActive: {
      type: Boolean,
      default: true,
      index: true,
    },
    approvalStatus: {
      type: String,
      enum: ['pending', 'approved', 'rejected'],
      default: 'pending',
      index: true,
    },
    moderationNote: {
      type: String,
      default: '',
      trim: true,
    },
    // PHASE 1 GAP FEATURES
    brand: {
      type: String,
      default: '',
      trim: true,
    },
    specifications: {
      type: mongoose.Schema.Types.Mixed,
      default: null,
    },
    specsUpdatedAt: {
      type: Date,
      default: null,
    },
    warranty: {
      type: WarrantySchema,
      default: null,
    },
    returnPolicy: {
      type: ReturnPolicySchema,
      default: null,
    },
    isDigital: {
      type: Boolean,
      default: false,
    },
    estimatedDeliveryDays: {
      type: Number,
      default: 5,
    },
    freeShipping: {
      type: Boolean,
      default: false,
    },
    salesCount: {
      type: Number,
      min: 0,
      default: 0,
    },
    gstRate: {
      type: String,
      enum: ['0%', '5%', '12%', '18%', '28%'],
      default: '18%',
    },
    hsnCode: {
      type: String,
      default: '9999',
    },
    isBusiness: {
      type: Boolean,
      default: false,
    },
    buyerGSTIN: {
      type: String,
      default: null,
    },
  },
  {
    timestamps: true,
  }
);

module.exports = mongoose.model('Product', ProductSchema);
